#pragma once

#include "PlatformTypes.h"
#include "Memory.h"
#include "TrackerDriverVersion.h"
#include "tracker_obx.h"
#include "legacy_obx.h" // the v1 family's header, generated by MADS from asm/Legacy/rmt_ata.a65

// Which of the loaded player's AUDF tables a note is read from, and where that table is (ported from RMT 1.36,
// plans 39 and 40: d81d88a, ffae5e7, d0863e8 and 0d22f0b).
//
// There are two layouts, because there are two generations of driver, and the driver version decides which one is
// read:
//
// PATCH16 (asm/Patch-16/rmtplayr.a65) chooses in two steps: its TABLES_MSB dispatch table maps the distortion to one
// of the five 256-byte pages at $B000, then store_tables_lsb picks a 64-byte slice by the channel's clock - 64 kHz
// at +$00, 1.79 MHz at +$40, 16-bit at +$80 - while check_15khz takes the two 15 kHz tables from PAGE_EXTRA_0.
//
// The v1 family - every other driver (asm/Legacy/rmt.a65) - has one page of 64-byte tables below the player, and
// its tabbeganddistor maps the distortion to a byte offset into that page. It has no clock variants: a 1.79 MHz or
// 15 kHz channel reads the very same table, which is why those two clocks play out of tune on those drivers.
//
// Both layouts are READ FROM THE DRIVER IN MEMORY rather than written down here: a private copy of the layout is how
// this went wrong twice, GetFrequency() with the RMT 1.28 offsets and the MIDI input with the RMT 1.34 addresses.
// For the v1 family it is a necessity too: only v1 has a source, and the five patched binaries each changed the
// table - PATCH6 plays distortion $06 with AUDC $A0 where v1 plays it with $C0, and PATCH8 and
// PATCH_PRINCE_OF_PERSIA do not even keep their tables on $40 boundaries.
class CFrequencyTables {
public:
    enum class Mode {
        Clock64kHz,
        Clock179MHz,
        Clock15kHz,
        Join16Bit,
    };

    // The v1-family layout. Both addresses are fixed by an `org` relative to PLAYER ($3400), so they hold for every
    // driver built from that source, whatever its feature flags. tabbeganddistor is eight (offset, AUDC) pairs
    // indexed by distortion / 2, the offset being a byte offset into the frqtab page.
    static constexpr MemoryAddress LEGACY_TABBEGANDDISTOR = RMT_ATA_TABBEGANDDISTOR;
    static constexpr MemoryAddress LEGACY_FRQTAB = RMT_ATA_FRQTAB;

    /// <summary> Whether the driver in `memory` really carries the table this version's layout reads </summary>
    /// <remarks> A plausibility check on the bytes, not a test of the version: it separates a loaded driver from an
    /// empty Atari and, measured on all seven drivers, a driver of one family from the other's layout. </remarks>
    static bool HasDispatchTable(const byte* memory, TrackerDriverVersion version);

    /// <summary> The address of the AUDF table the player reads for this distortion and mode </summary>
    /// <param name="memory"> the emulated Atari's memory, with a driver loaded </param>
    /// <param name="version"> which driver that is, and so which layout to read </param>
    /// <param name="distortion"> the instrument's RMT distortion, $00 to $0E </param>
    /// <returns> The table's address, or 0 when the loaded driver has no such table. The table holds 64 bytes,
    /// except in Join16Bit mode on PATCH16, where it holds 64 little-endian words. The v1 family answers 0 for
    /// Join16Bit: its 16-bit bass reads two tables a page apart (frqtabbasslo/frqtabbasshi), which no single address
    /// can name. </returns>
    static MemoryAddress GetTableAddress(const byte* memory, TrackerDriverVersion version, int distortion, Mode mode);

    /// <summary> Which clock or width a channel plays at, from the AUDCTL the driver is about to write </summary>
    /// <param name="audctl"> the AUDCTL value, as in the driver's v_audctl </param>
    /// <param name="track"> the POKEY channel, 0-3 for the first chip and 4-7 for the second </param>
    /// <remarks> Only channels 1 and 3 of each chip can run at 1.79 MHz (tracks 0/4 and 2/6), and a 16-bit pair is
    /// addressed through its high byte, the channel above (tracks 1/5 and 3/7). 1.79 MHz and 16-bit both override the
    /// 15 kHz clock, as they do in the player. </remarks>
    static Mode GetModeForChannel(int audctl, int track);

    /// <summary> The AUDC distortion bits the player writes to POKEY for this distortion </summary>
    /// <returns> The AUDC value, or -1 when the loaded driver has no dispatch table. Read from that table, because it
    /// is not simply the distortion shifted up, and not even the same from driver to driver. </returns>
    static int GetDistortionAudc(const byte* memory, TrackerDriverVersion version, int distortion);
};
